<?php
require_once __DIR__.'/includes/functions.php';require_role(['admin','librarian']);$pageTitle='Manage books';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='save'){
  $id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$author=trim($_POST['author']??'');$category=(int)($_POST['category_id']??0);$isbn=trim($_POST['isbn']??'');$publisher=trim($_POST['publisher']??'');$year=(int)($_POST['publication_year']??0);$qty=(int)($_POST['total_quantity']??0);$desc=trim($_POST['description']??'');
  if($title===''||$author===''||$qty<0){$error='Title, author, and a non-negative quantity are required.';}
  elseif($year && ($year<1450 || $year>(int)date('Y')+1)){$error='Enter a valid publication year.';}
  else {
   $existing=null;if($id){$x=db()->prepare('SELECT * FROM books WHERE id=?');$x->execute([$id]);$existing=$x->fetch();if(!$existing)$error='Book not found.';}
   $cover=$existing['cover_image']??null;
   if(!$error && isset($_FILES['cover']) && $_FILES['cover']['error']!==UPLOAD_ERR_NO_FILE){
    $f=$_FILES['cover'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
    if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024||!isset($allowed[$mime]))$error='Cover must be JPG, PNG, or WebP and no larger than 2 MB.';
    else{$cover=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/covers/'.$cover)){$cover=null;$error='Unable to save cover image.';}}
   }
   if(!$error){
    if($existing){$onLoan=(int)$existing['total_quantity']-(int)$existing['available_quantity'];if($qty<$onLoan)$error='Total quantity cannot be less than the number currently issued.';else{$available=$qty-$onLoan;$s=db()->prepare('UPDATE books SET title=?,author=?,category_id=?,isbn=?,publisher=?,publication_year=?,description=?,total_quantity=?,available_quantity=?,cover_image=? WHERE id=?');$s->execute([$title,$author,$category?:null,$isbn?:null,$publisher?:null,$year?:null,$desc?:null,$qty,$available,$cover,$id]);}}
    else{$s=db()->prepare('INSERT INTO books(title,author,category_id,isbn,publisher,publication_year,description,total_quantity,available_quantity,cover_image) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$title,$author,$category?:null,$isbn?:null,$publisher?:null,$year?:null,$desc?:null,$qty,$qty,$cover]);}
    if(!$error){flash('success',$existing?'Book updated successfully.':'Book added successfully.');redirect('/books.php');}
   }
  }
 }elseif($action==='delete'){$id=(int)($_POST['id']??0);$s=db()->prepare("SELECT COUNT(*) FROM issues WHERE book_id=? AND status='issued'");$s->execute([$id]);if((int)$s->fetchColumn()>0)$error='This book has active loans and cannot be archived.';else{$s=db()->prepare('UPDATE books SET is_active=0 WHERE id=?');$s->execute([$id]);flash('success','Book removed from the active catalog.');redirect('/books.php');}}
}
$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM books WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
$cats=db()->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$books=db()->query('SELECT b.*,c.name AS category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.is_active=1 ORDER BY b.created_at DESC')->fetchAll();
require __DIR__.'/includes/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><p class="text-primary small text-uppercase fw-bold mb-1">Library operations</p><h1 class="page-title mb-1">Manage books</h1><p class="muted mb-0">Add titles, update stock, and keep the catalog accurate.</p></div><a href="dashboard.php" class="btn btn-outline-primary">Dashboard</a></div>
<?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?>
<div class="surface p-3 p-md-4 mb-4"><h2 class="h5 fw-bold mb-3"><?=$edit?'Edit book':'Add a book'?></h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Book title *</label><input class="form-control" name="title" required maxlength="200" value="<?=e($edit['title']??'')?>"></div><div class="col-md-6"><label class="form-label">Author *</label><input class="form-control" name="author" required maxlength="150" value="<?=e($edit['author']??'')?>"></div><div class="col-md-4"><label class="form-label">Category</label><select class="form-select" name="category_id"><option value="0">Select category</option><?php foreach($cats as $c): ?><option value="<?=(int)$c['id']?>" <?=((int)($edit['category_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">ISBN</label><input class="form-control" name="isbn" maxlength="20" value="<?=e($edit['isbn']??'')?>"></div><div class="col-md-4"><label class="form-label">Publisher</label><input class="form-control" name="publisher" maxlength="150" value="<?=e($edit['publisher']??'')?>"></div><div class="col-md-4"><label class="form-label">Publication year</label><input class="form-control" type="number" min="1450" max="<?=date('Y')+1?>" name="publication_year" value="<?=e((string)($edit['publication_year']??''))?>"></div><div class="col-md-4"><label class="form-label">Total copies *</label><input class="form-control" type="number" min="0" name="total_quantity" required value="<?=e((string)($edit['total_quantity']??1))?>"></div><div class="col-md-4"><label class="form-label">Cover image (JPG, PNG, WebP; max 2 MB)</label><input class="form-control" type="file" name="cover" accept="image/jpeg,image/png,image/webp"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="3" name="description"><?=e($edit['description']??'')?></textarea></div><div class="col-12 d-flex gap-2"><button class="btn btn-primary" type="submit"><i class="bi bi-check2 me-1"></i><?=$edit?'Save changes':'Add book'?></button><?php if($edit): ?><a href="books.php" class="btn btn-light">Cancel edit</a><?php endif; ?></div></div></form></div>
<div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold mb-0">Catalog inventory <span class="muted">(<?=count($books)?>)</span></h2><input class="form-control" style="max-width:260px" placeholder="Filter this table..." data-search-target="#bookRows"></div><div class="table-wrap"><table class="table"><thead><tr><th>Book</th><th>Category</th><th>ISBN</th><th>Stock</th><th>Available</th><th>Actions</th></tr></thead><tbody id="bookRows"><?php foreach($books as $b): ?><tr data-searchable><td><div class="d-flex align-items-center gap-3"><img class="mini-cover" src="<?=e(cover_url($b['cover_image']))?>" alt=""><div><strong><?=e($b['title'])?></strong><div class="small muted"><?=e($b['author'])?></div></div></div></td><td><?=e($b['category_name']??'—')?></td><td><?=e($b['isbn']??'—')?></td><td><?=(int)$b['total_quantity']?></td><td><?=(int)$b['available_quantity']?></td><td><div class="d-flex gap-1"><a class="btn btn-sm btn-outline-primary" href="books.php?edit=<?=(int)$b['id']?>"><i class="bi bi-pencil"></i></a><form method="post" onsubmit="return confirm('Remove this book from the active catalog?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><button class="btn btn-sm btn-outline-danger" type="submit"><i class="bi bi-archive"></i></button></form></div></td></tr><?php endforeach; ?></tbody></table><?php if(!$books): ?><div class="empty-state">No books in the catalog yet.</div><?php endif; ?></div>
<?php require __DIR__.'/includes/footer.php'; ?>
